  const unknown = (reason) =&gt; ({ status: 'unknown', supported: false, reason, claims: [] });
  if (!claims.length || !sources.length) return unknown('No claims or readable evidence');
  if (claims.length &gt; 24) return unknown('Claim limit exceeded');
